            entry._createdKey = null;
            state.results.push({
                type: 'Story',
                summary: buildSummary(entry.summary, 0),
                key: null,
                success: false,
                error: 'Could not resolve parent "' + entry.parent + '"'
            });
            return;
        }

        var key = createStory(entry, parent.parent, ctx.projectKey);
        var summary = buildSummary(entry.summary, 0);
        if (key) {
