        var mod = d3LoadCheckTask({
            ado_search_by_wiql: function() { n++; return { value: n === 1 ? [{ id: 1, fields: { 'System.Title': 'S', 'System.State': 'Done' } }] : [] }; },
            ado_move_to_state: function(a) { calls.push(['move', a]); },
