// Recorder mock for every jira tool the intake action can touch.
function intakeRecorder() {
    var calls = [];
    var keyCounter = 100;
    var api = {
        calls: calls,
        nextKey: function() { return 'P-' + (keyCounter++); },
        failCreate: false
    };
