        entry._createdKey = key;
        attachFilesToTicket(key, entry);
        linkToSource(key, ctx.ticketKey);
        state.results.push({
            type: 'Bug',
            summary: summary,
            key: key,
            success: !!key,
            error: key ? null : 'Creation failed (see logs)'
