    try {
        tracker.removeLabel(ctx.ticketKey, ctx.wipLabel);
        console.log('Removed WIP label "' + ctx.wipLabel + '" from ' + ctx.ticketKey);
    } catch (wipError) {
        console.warn('Failed to remove WIP label:', wipError);
    }
