            if (key && entry.tempId) {
                state.tempIdMap[entry.tempId] = key;
                state.keyMap[entry.tempId] = key;
                console.log('Mapped tempId ' + entry.tempId + ' -> ' + key);
            }
            if (key) state.keyMap[key] = key;
            entry._createdKey = key; // track for pass 4
