function resolveParentRef(entry, keyMap) {
    if (keyMap[entry.parent]) {
        return { resolved: true, parent: keyMap[entry.parent] };
    }
    if (!/^[A-Z]+-\d+$/.test(entry.parent)) {
        return { resolved: false, parent: null };
