function linkBlockedByRef(blockedKey, ref, keyMap) {
    var blockerKey = resolveKey(ref, keyMap);
    if (!blockerKey) {
        console.warn('Cannot resolve blockedBy ref "' + ref + '" for ' + blockedKey);
        return false;
    }
    try {
        tracker.linkIssues(blockedKey, blockerKey, 'Blocks');
